<script setup lang="ts">import {usePropertyStore} from '@/hooks/property';import {calendarFlipDefaults} from '@/calendar-flip';const property=usePropertyStore();</script><template><section><h3>木纹日历翻页时钟</h3><p>月 · 日 · 时 · 分 · 秒独立翻牌</p><label>翻页动画<input type="checkbox" :checked="property.settings.animate!==false" @change="property.settings.animate=($event.target as HTMLInputElement).checked"></label><label>动画速度<select :value="property.settings.duration||440" @change="property.settings.duration=Number(($event.target as HTMLSelectElement).value)"><option :value="260">快速</option><option :value="440">标准</option><option :value="760">舒缓</option></select></label><label>木纹<select :value="property.settings.wood||'maple'" @change="property.settings.wood=($event.target as HTMLSelectElement).value"><option value="maple">浅色枫木</option><option value="walnut">深色胡桃木</option></select></label><label>标签<select :value="property.settings.labels||'en'" @change="property.settings.labels=($event.target as HTMLSelectElement).value"><option value="en">英文</option><option value="zh">中文</option></select></label><label>12 小时制<input type="checkbox" :checked="property.settings.hour12===true" @change="property.settings.hour12=($event.target as HTMLInputElement).checked"></label><label>图像传输<select :value="property.settings.transport||'compatible'" @change="property.settings.transport=($event.target as HTMLSelectElement).value"><option value="compatible">兼容模式</option><option value="binary">二进制 PNG（实验）</option></select></label><button @click="Object.assign(property.settings,calendarFlipDefaults)">恢复默认</button></section></template><style scoped>section{padding:16px;color:#eee;font:13px 'Microsoft YaHei',sans-serif}label{display:flex;justify-content:space-between;align-items:center;gap:12px;margin:16px 0}p{opacity:.65;line-height:1.7}button,select{padding:7px;background:#392b20;color:#fff;border:1px solid #8d7357;border-radius:5px}button{cursor:pointer}</style>
